"""Transform function for task-efff2ac7."""
from collections import deque

def transform(grid):
    """Fill enclosed background regions with color 4."""
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    queue = deque()

    # Start from all edge cells
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] == bg:
                visited[r][c] = True
                queue.append((r, c))

    directions = [(0,1), (0,-1), (1,0), (-1,0)]
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == bg:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Fill unvisited background cells
    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and not visited[r][c]:
                result[r][c] = 4
    return result

